"""One-file, offline, zero-network control tower for public GitHub docket.

Renders links only from the previously validated GitHub source docket. The
HTML is a PRIVATE review view; do not publish private host snapshots by default.
"""
from __future__ import annotations
import html,json
from pathlib import Path
from .docket import load_docket,classify_backlog

def render_dashboard(docket:dict, proof:dict, *, optional_private_host_status:dict|None=None)->str:
    rows=load_docket(docket);counts=classify_backlog(rows)
    if type(proof) is not dict or proof.get('schema')!='atlas.one.source-unity.review/v0.3':
        raise ValueError('verified_local_proof_required')
    serial=json.dumps(rows,ensure_ascii=False,separators=(',',':')).replace('</','<\\/')
    host=optional_private_host_status if type(optional_private_host_status) is dict else {}
    hosttext=f"{int(host['offline_source'])} of {int(host['total'])} evidence gates" if all(k in host for k in ('offline_source','total')) else 'Not supplied'
    repo_counts=sorted(counts['repos'].items(),key=lambda item:sum(item[1].values()),reverse=True)
    report_items=''.join('<div class="repo"><div class="rname">'+html.escape(repo)+
                  '</div><div class="rbar"><span style="width:'+str(round(100*(v.get('PR',0)+v.get('ISSUE',0))/max(1,counts['observed_total']),2))+ '%"></span></div><div class="n">'+str(v.get('PR',0)+v.get('ISSUE',0))+'</div></div>' for repo,v in repo_counts)
    return '''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Atlas ONE · Source Control Tower</title>
<style>
:root{--bg:#0a1319;--panel:#12222a;--raised:#182c33;--border:#2a4249;--ink:#eaf4ef;--muted:#9eb5b8;--lime:#b3f36a;--yellow:#f6cb7b;--blue:#85d5f2;--red:#ef998c}*{box-sizing:border-box}body{background:radial-gradient(ellipse 100% 45% at 60% -20%,#1a3d39,transparent),var(--bg);color:var(--ink);font:15px/1.5 system-ui,sans-serif;margin:0}a{color:var(--blue);text-decoration:none}a:hover{text-decoration:underline}.wrap{max-width:1320px;margin:auto;padding:24px}.top{display:flex;justify-content:space-between;gap:18px;align-items:center;flex-wrap:wrap;padding:25px 0;border-bottom:1px solid var(--border)}.sup{color:var(--lime);letter-spacing:.22em;text-transform:uppercase;font-size:11px;font-weight:800}.top h1{font-size:clamp(26px,4vw,45px);line-height:1.08;margin:8px 0}.meta{color:var(--muted);max-width:760px}.chip{border:1px solid var(--border);border-radius:100px;padding:8px 12px;color:var(--yellow);font-size:12px;background:#243237}.tiles{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:14px;margin:22px 0}.tile{background:var(--panel);border:1px solid var(--border);border-radius:14px;padding:19px}.big{font-size:clamp(24px,4vw,41px);font-weight:800;letter-spacing:-.05em;font-variant-numeric:tabular-nums}.lbl{color:var(--muted);font-size:12px}.wide{display:grid;grid-template-columns:1.07fr .93fr;gap:18px;margin:16px 0}.card{background:var(--panel);border:1px solid var(--border);border-radius:16px;padding:20px}.card h2{font-size:17px;margin:0 0 12px}.status{display:flex;align-items:center;gap:10px;padding:10px 0;border-top:1px solid var(--border)}.status b{font-size:12px}.dot{width:8px;height:8px;border-radius:50%;background:var(--yellow);flex-shrink:0}.dot.ok{background:var(--lime)}.status small{color:var(--muted);display:block}.repo{display:grid;grid-template-columns:200px 1fr 36px;align-items:center;gap:10px;margin:8px 0}.rname{font-size:12px;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}.rbar{background:#273e45;height:9px;border-radius:9px;overflow:hidden}.rbar span{display:block;height:100%;background:linear-gradient(90deg,#57a5af,var(--lime));border-radius:9px}.n{text-align:right;font-size:12px;font-variant-numeric:tabular-nums}.filters{display:flex;gap:9px;flex-wrap:wrap;margin:12px 0 16px}.filters>*{background:var(--raised);color:var(--ink);border:1px solid var(--border);border-radius:8px;padding:9px 11px;font:inherit}.filters input{flex:1;min-width:240px}.tablebox{overflow:auto;border:1px solid var(--border);border-radius:12px;max-height:710px}table{border-collapse:collapse;width:100%;min-width:720px}th{background:#1b333b;position:sticky;top:0;z-index:1;color:var(--muted);text-transform:uppercase;letter-spacing:.1em;font-size:11px;text-align:left}td,th{padding:12px;border-bottom:1px solid #294147}td{font-size:13px}td.repoCell{font-size:11px;color:var(--muted)}.tag{border:1px solid #465f64;border-radius:5px;padding:3px 7px;white-space:nowrap;font-size:10px}.tag.pr{color:var(--lime)}.tag.issue{color:var(--blue)}.bottom{padding:32px 0;color:var(--muted);font-size:12px}code{color:var(--lime)}@media(max-width:760px){.tiles{grid-template-columns:1fr 1fr}.wide{grid-template-columns:1fr}.repo{grid-template-columns:145px 1fr 33px}.wrap{padding:12px}}
</style></head><body><div class="wrap"><header class="top"><div><div class="sup">Atlas Intelligence · Alexandria · Ariadne · AtlasGPT · SwarmChat · CANON</div><h1>ONE PROJECT<br><span style="color:var(--lime)">Evidence Control Tower</span></h1><div class="meta">Version 0.3 · November 22, 2026 · Offline, source-only. Unified addresses and evidence, separately governed rights. This dashboard performs no network request, model wake, task closure, or GitHub mutation.</div></div><div class="chip">HOST RELEASE HELD · NOT CANON</div></header>
<section class="tiles"><div class="tile"><div class="big">'''+str(counts['observed_total'])+'''</div><div class="lbl">Observed open GitHub records</div></div><div class="tile"><div class="big">'''+str(counts['observed_open_prs'])+'''</div><div class="lbl">Open pull requests</div></div><div class="tile"><div class="big">'''+str(counts['observed_open_issues'])+'''</div><div class="lbl">Open GitHub issues</div></div><div class="tile"><div class="big">1,728</div><div class="lbl">Paired abstract coordinate slots — NOT verified semantics</div></div></section>
<section class="wide"><div class="card"><h2>Integrated source pipeline</h2>
<div class="status"><span class="dot ok"></span><div><b>Atlas ONE circuit · 8 source events</b><small>Local trace replayed; SHA-256-linked, no signed host identity</small></div></div>
<div class="status"><span class="dot ok"></span><div><b>Noosphere · public-source handoff</b><small>Actual source validator called; reported partial export not complete</small></div></div>
<div class="status"><span class="dot ok"></span><div><b>Ariadne ↔ GF7 · reversible index mapping</b><small>All 1,728 pairs; zero physical calibration and zero semantic identity</small></div></div>
<div class="status"><span class="dot"></span><div><b>SwarmChat host · authority gate</b><small>'''+html.escape(hosttext)+''' · resident authentication and rights-at-return not independently verified</small></div></div>
<div class="status"><span class="dot"></span><div><b>GitHub Actions · runner admission</b><small>Multiple zero-step failures; root cause unknown; local passing ≠ hosted passing</small></div></div>
<div class="status"><span class="dot"></span><div><b>CANON and research claims</b><small>Candidate-only; independent peer review, source rights and physical data still required</small></div></div></div>
<div class="card"><h2>Observed work concentration</h2>'''+report_items+'''<p style="color:var(--muted);font-size:12px;margin-top:18px">The full docket is a non-atomic GitHub search snapshot, not a census of private Work, Notion tasks, or runtime agents. Exact URLs retain source identity.</p></div></section>
<section class="card" style="margin-top:18px"><h2>All open GitHub items · source-linked</h2><p class="meta">These rows are neither verified completions nor approved merge targets. Filter them to route human review. A search result may have changed since this snapshot.</p><div class="filters"><input id="search" aria-label="Search issues and pull requests" placeholder="Find source, PR, dependency, subsystem..."/><select id="kind" aria-label="Type"><option value="">All types</option><option value="PR">PRs</option><option value="ISSUE">Issues</option></select><select id="repo" aria-label="Repository"><option value="">All repositories</option></select><select id="theme" aria-label="Theme"><option value="">All themes</option></select></div><div id="count" class="lbl" aria-live="polite"></div><div class="tablebox"><table><thead><tr><th>Type</th><th>Repository</th><th>#</th><th>Title / source link</th><th>Classification</th></tr></thead><tbody id="rows"></tbody></table></div></section><footer class="bottom">One project does not mean one undifferentiated permission, one mythology, one scientific truth claim, or one always-on AI. Every source edition, ownership boundary, disagreement and rollback path survives.</footer></div>
<script id="seed" type="application/json">'''+serial+'''</script><script>
(()=>{const items=JSON.parse(document.getElementById('seed').textContent);const search=document.getElementById('search'),kind=document.getElementById('kind'),repo=document.getElementById('repo'),theme=document.getElementById('theme'),tbody=document.getElementById('rows'),counter=document.getElementById('count');const clean=(s)=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const opts=(node,values)=>values.sort().forEach(s=>{let e=document.createElement('option');e.value=s;e.textContent=s;node.append(e)});opts(repo,[...new Set(items.map(x=>x.repository))]);opts(theme,[...new Set(items.map(x=>x.theme))]);function draw(){let q=search.value.toLowerCase().trim(),rows=items.filter(x=>(!q||(x.title+' '+x.repository+' '+x.number).toLowerCase().includes(q))&&(!kind.value||x.kind===kind.value)&&(!repo.value||x.repository===repo.value)&&(!theme.value||x.theme===theme.value));counter.textContent=rows.length+' observed source-linked records · 0 automatically closed/merged';tbody.innerHTML=rows.map(x=>'<tr><td><span class="tag '+(x.kind==='PR'?'pr':'issue')+'">'+x.kind+'</span></td><td class="repoCell">'+clean(x.repository)+'</td><td>#'+x.number+'</td><td><a target="_blank" rel="noopener noreferrer" href="'+x.url+'">'+clean(x.title)+'</a></td><td>'+clean(x.theme)+'</td></tr>').join('')}[search,kind,repo,theme].forEach(e=>e.addEventListener('input',draw));draw()})();
</script></body></html>'''


def main(argv=None):
    import argparse
    a=argparse.ArgumentParser();a.add_argument('--docket',required=True,type=Path);a.add_argument('--proof',required=True,type=Path);a.add_argument('--output',required=True,type=Path);a.add_argument('--private-host-status',type=Path)
    x=a.parse_args(argv)
    d=json.loads(x.docket.read_text('utf-8-sig'));p=json.loads(x.proof.read_text('utf-8'))
    h=json.loads(x.private_host_status.read_text('utf-8')) if x.private_host_status else None
    x.output.parent.mkdir(parents=True,exist_ok=True);x.output.write_text(render_dashboard(d,p,optional_private_host_status=h),encoding='utf-8')
    print(x.output)

if __name__=='__main__':main()
